CREATE TABLE IF NOT EXISTS "projects" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- URL segment and the name used in the CLI, e.g. acme/api.
	"slug" VARCHAR(120) NOT NULL UNIQUE,
	-- Human-readable project name.
	"display_name" VARCHAR(200) NOT NULL,
	-- Clone URL the runner checks out from. Stored per project because a build cannot start without it.
	"repository_url" VARCHAR(500) NOT NULL,
	-- Branch treated as the trunk, which decides what counts as a mainline build in dashboards.
	"default_branch" VARCHAR(255) NOT NULL DEFAULT 'main',
	-- Maximum simultaneous runs. A project-level limit rather than a global one, because one noisy repository must not starve every other.
	"concurrency_limit" INTEGER NOT NULL DEFAULT 4,
	-- How long artifacts survive. Storage, not compute, is what makes a CI bill grow without anyone noticing.
	"artifact_retention_days" INTEGER NOT NULL DEFAULT 30,
	-- False pauses all triggering without deleting history.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "projects" IS 'A thing that gets built. Everything schedulable is scoped to a project, which is how limits, quotas and retention are enforced without a second tenancy concept.';
COMMENT ON COLUMN "projects"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "projects"."slug" IS 'URL segment and the name used in the CLI, e.g. acme/api.';
COMMENT ON COLUMN "projects"."display_name" IS 'Human-readable project name.';
COMMENT ON COLUMN "projects"."repository_url" IS 'Clone URL the runner checks out from. Stored per project because a build cannot start without it.';
COMMENT ON COLUMN "projects"."default_branch" IS 'Branch treated as the trunk, which decides what counts as a mainline build in dashboards.';
COMMENT ON COLUMN "projects"."concurrency_limit" IS 'Maximum simultaneous runs. A project-level limit rather than a global one, because one noisy repository must not starve every other.';
COMMENT ON COLUMN "projects"."artifact_retention_days" IS 'How long artifacts survive. Storage, not compute, is what makes a CI bill grow without anyone noticing.';
COMMENT ON COLUMN "projects"."is_active" IS 'False pauses all triggering without deleting history.';
COMMENT ON COLUMN "projects"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "pipeline_definitions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning project.
	"project_id" BIGINT NOT NULL,
	-- Pipeline name, e.g. ci or nightly. Several pipelines per project is normal.
	"name" VARCHAR(120) NOT NULL,
	-- Monotonic version within the pipeline name. A new version is inserted rather than updating the previous one, so a run can point at exactly the configuration it used.
	"version" INTEGER NOT NULL,
	-- Where the definition came from, e.g. .ci/pipeline.yml at a commit. The file is in git; this records which path produced this row.
	"config_source" VARCHAR(500) NOT NULL,
	-- Commit the configuration was read from. Two runs claiming the same definition version must have read the same bytes, and this is what proves it.
	"config_sha" CHAR(40) NOT NULL,
	-- The raw configuration as parsed. Stored in full, because a run six months old must be explainable even if the file has since been deleted from the repository.
	"config_body" TEXT NOT NULL,
	-- Whether new triggers use this version. Exactly one row per name is current; older ones stay for the runs that reference them.
	"is_current" BOOLEAN NOT NULL DEFAULT true,
	-- When the version was registered.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "pipeline_definitions" IS 'A versioned, immutable snapshot of pipeline configuration. Editing a definition in place is the shortcut that makes every historical run a lie about what it actually ran.';
COMMENT ON COLUMN "pipeline_definitions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "pipeline_definitions"."project_id" IS 'Owning project.';
COMMENT ON COLUMN "pipeline_definitions"."name" IS 'Pipeline name, e.g. ci or nightly. Several pipelines per project is normal.';
COMMENT ON COLUMN "pipeline_definitions"."version" IS 'Monotonic version within the pipeline name. A new version is inserted rather than updating the previous one, so a run can point at exactly the configuration it used.';
COMMENT ON COLUMN "pipeline_definitions"."config_source" IS 'Where the definition came from, e.g. .ci/pipeline.yml at a commit. The file is in git; this records which path produced this row.';
COMMENT ON COLUMN "pipeline_definitions"."config_sha" IS 'Commit the configuration was read from. Two runs claiming the same definition version must have read the same bytes, and this is what proves it.';
COMMENT ON COLUMN "pipeline_definitions"."config_body" IS 'The raw configuration as parsed. Stored in full, because a run six months old must be explainable even if the file has since been deleted from the repository.';
COMMENT ON COLUMN "pipeline_definitions"."is_current" IS 'Whether new triggers use this version. Exactly one row per name is current; older ones stay for the runs that reference them.';
COMMENT ON COLUMN "pipeline_definitions"."created_at" IS 'When the version was registered.';

CREATE UNIQUE INDEX "uq_pipeline_definitions_project_name_version"
ON "pipeline_definitions" ("project_id", "name", "version");
CREATE INDEX "idx_pipeline_definitions_current"
ON "pipeline_definitions" ("project_id", "name", "is_current");

CREATE TABLE IF NOT EXISTS "pipeline_runs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Project being built.
	"project_id" BIGINT NOT NULL,
	-- Exact configuration version this run expanded. Never the current version at read time: that is the whole point of versioning the definition.
	"pipeline_definition_id" BIGINT NOT NULL,
	-- Run this one re-executes. Null for an original. A rerun is a new row, so the failed run keeps its logs, timings and artifacts forever.
	"rerun_of_run_id" BIGINT,
	-- Per-project counter people quote in chat. Monotonic and never reused, including by reruns, which get their own number.
	"run_number" INTEGER NOT NULL,
	-- push | pull_request | schedule | manual | api | upstream. Reruns carry the type of the original plus a rerun_of link, so a schedule that fails and is retried is still countable as a schedule.
	"trigger_type" VARCHAR(24) NOT NULL,
	-- Identity that caused it, a login or a bot name. Null for a schedule, which is meaningfully different from an anonymous trigger.
	"triggered_by" VARCHAR(120),
	-- Commit being built. The immutable input: the same SHA and the same definition should give the same result, and when they do not, that is the bug.
	"commit_sha" CHAR(40) NOT NULL,
	-- Subject line, snapshotted so a build list is readable without cloning the repository.
	"commit_message" VARCHAR(500),
	-- Branch or tag at trigger time, e.g. refs/heads/main. Text, because the ref may be deleted before the run finishes.
	"ref_name" VARCHAR(255) NOT NULL,
	-- queued | running | completed | cancelled.
	"status" VARCHAR(20) NOT NULL DEFAULT 'queued',
	-- success | failure | timed_out | skipped. Null until status is completed; a run in flight has no outcome, and one column cannot say that.
	"conclusion" VARCHAR(20),
	-- When the trigger was accepted. Queue time is started_at minus this, and it is the number that tells you to buy more runners.
	"queued_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When the first job began.
	"started_at" TIMESTAMP,
	-- When the last job settled.
	"finished_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "pipeline_runs" IS 'One immutable execution of one definition version against one commit. Nothing here is ever edited after the run settles; a retry inserts a new row pointing back at this one.';
COMMENT ON COLUMN "pipeline_runs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "pipeline_runs"."project_id" IS 'Project being built.';
COMMENT ON COLUMN "pipeline_runs"."pipeline_definition_id" IS 'Exact configuration version this run expanded. Never the current version at read time: that is the whole point of versioning the definition.';
COMMENT ON COLUMN "pipeline_runs"."rerun_of_run_id" IS 'Run this one re-executes. Null for an original. A rerun is a new row, so the failed run keeps its logs, timings and artifacts forever.';
COMMENT ON COLUMN "pipeline_runs"."run_number" IS 'Per-project counter people quote in chat. Monotonic and never reused, including by reruns, which get their own number.';
COMMENT ON COLUMN "pipeline_runs"."trigger_type" IS 'push | pull_request | schedule | manual | api | upstream. Reruns carry the type of the original plus a rerun_of link, so a schedule that fails and is retried is still countable as a schedule.';
COMMENT ON COLUMN "pipeline_runs"."triggered_by" IS 'Identity that caused it, a login or a bot name. Null for a schedule, which is meaningfully different from an anonymous trigger.';
COMMENT ON COLUMN "pipeline_runs"."commit_sha" IS 'Commit being built. The immutable input: the same SHA and the same definition should give the same result, and when they do not, that is the bug.';
COMMENT ON COLUMN "pipeline_runs"."commit_message" IS 'Subject line, snapshotted so a build list is readable without cloning the repository.';
COMMENT ON COLUMN "pipeline_runs"."ref_name" IS 'Branch or tag at trigger time, e.g. refs/heads/main. Text, because the ref may be deleted before the run finishes.';
COMMENT ON COLUMN "pipeline_runs"."status" IS 'queued | running | completed | cancelled.';
COMMENT ON COLUMN "pipeline_runs"."conclusion" IS 'success | failure | timed_out | skipped. Null until status is completed; a run in flight has no outcome, and one column cannot say that.';
COMMENT ON COLUMN "pipeline_runs"."queued_at" IS 'When the trigger was accepted. Queue time is started_at minus this, and it is the number that tells you to buy more runners.';
COMMENT ON COLUMN "pipeline_runs"."started_at" IS 'When the first job began.';
COMMENT ON COLUMN "pipeline_runs"."finished_at" IS 'When the last job settled.';

CREATE UNIQUE INDEX "uq_pipeline_runs_project_number"
ON "pipeline_runs" ("project_id", "run_number");
CREATE INDEX "idx_pipeline_runs_project_status"
ON "pipeline_runs" ("project_id", "status");
CREATE INDEX "idx_pipeline_runs_commit"
ON "pipeline_runs" ("commit_sha");
CREATE INDEX "idx_pipeline_runs_rerun_of"
ON "pipeline_runs" ("rerun_of_run_id");

CREATE TABLE IF NOT EXISTS "run_stages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Run this stage belongs to. Stages are materialised per run rather than shared, because the definition can change between runs.
	"run_id" BIGINT NOT NULL,
	-- Stage name, e.g. build, test, deploy.
	"name" VARCHAR(80) NOT NULL,
	-- Display order. Stages are a presentation and gating device; the real ordering constraint lives in the job edges.
	"position" INTEGER NOT NULL,
	-- Whether a human must approve before jobs in this stage start. Typically true for deploy, and it is the reason stages exist at all rather than being pure UI.
	"requires_approval" BOOLEAN NOT NULL DEFAULT false,
	-- Who approved. Null when not required or not yet given.
	"approved_by" VARCHAR(120),
	-- When approval was granted. The gap from the previous stage finishing is deploy lead time.
	"approved_at" TIMESTAMP,
	-- pending | running | completed | skipped | blocked.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "run_stages" IS 'A named, ordered group of jobs within one run. It carries the approval gate; everything else about ordering is expressed as dependencies between jobs, not by stage boundaries.';
COMMENT ON COLUMN "run_stages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "run_stages"."run_id" IS 'Run this stage belongs to. Stages are materialised per run rather than shared, because the definition can change between runs.';
COMMENT ON COLUMN "run_stages"."name" IS 'Stage name, e.g. build, test, deploy.';
COMMENT ON COLUMN "run_stages"."position" IS 'Display order. Stages are a presentation and gating device; the real ordering constraint lives in the job edges.';
COMMENT ON COLUMN "run_stages"."requires_approval" IS 'Whether a human must approve before jobs in this stage start. Typically true for deploy, and it is the reason stages exist at all rather than being pure UI.';
COMMENT ON COLUMN "run_stages"."approved_by" IS 'Who approved. Null when not required or not yet given.';
COMMENT ON COLUMN "run_stages"."approved_at" IS 'When approval was granted. The gap from the previous stage finishing is deploy lead time.';
COMMENT ON COLUMN "run_stages"."status" IS 'pending | running | completed | skipped | blocked.';

CREATE UNIQUE INDEX "uq_run_stages_run_position"
ON "run_stages" ("run_id", "position");

CREATE TABLE IF NOT EXISTS "jobs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Run this job belongs to. A job is a node in one run graph and is never shared between runs.
	"run_id" BIGINT NOT NULL,
	-- Stage it is displayed and gated under. Null for a job that runs outside any stage, such as a setup step.
	"stage_id" BIGINT,
	-- Job name with matrix values already expanded, e.g. test (linux, node-20). Expansion happens once, at run creation, so the graph is fully materialised before anything is scheduled.
	"name" VARCHAR(200) NOT NULL,
	-- Runner labels this job needs, comma separated, e.g. linux,docker,gpu. Matched against runner_capabilities at scheduling time.
	"required_labels" VARCHAR(300),
	-- Whether a failure here still lets dependants run. This is why a job outcome and a run outcome are computed separately.
	"allow_failure" BOOLEAN NOT NULL DEFAULT false,
	-- Wall-clock limit. Enforced by the scheduler, not the runner, because a wedged runner cannot time itself out.
	"timeout_seconds" INTEGER NOT NULL DEFAULT 3600,
	-- How many times this job may be retried automatically. Retries create attempt rows; the job row itself never changes.
	"max_attempts" INTEGER NOT NULL DEFAULT 1,
	-- pending | blocked | queued | running | completed | skipped. Blocked means an upstream edge is unsatisfied, which is distinct from waiting for a runner.
	"status" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- success | failure | cancelled | skipped. Rolled up from the last attempt once the job settles.
	"conclusion" VARCHAR(20),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "jobs" IS 'A node in the run DAG. It describes what should happen; every actual execution of it lives in job_attempts, which is what makes retries expressible without rewriting the graph.';
COMMENT ON COLUMN "jobs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "jobs"."run_id" IS 'Run this job belongs to. A job is a node in one run graph and is never shared between runs.';
COMMENT ON COLUMN "jobs"."stage_id" IS 'Stage it is displayed and gated under. Null for a job that runs outside any stage, such as a setup step.';
COMMENT ON COLUMN "jobs"."name" IS 'Job name with matrix values already expanded, e.g. test (linux, node-20). Expansion happens once, at run creation, so the graph is fully materialised before anything is scheduled.';
COMMENT ON COLUMN "jobs"."required_labels" IS 'Runner labels this job needs, comma separated, e.g. linux,docker,gpu. Matched against runner_capabilities at scheduling time.';
COMMENT ON COLUMN "jobs"."allow_failure" IS 'Whether a failure here still lets dependants run. This is why a job outcome and a run outcome are computed separately.';
COMMENT ON COLUMN "jobs"."timeout_seconds" IS 'Wall-clock limit. Enforced by the scheduler, not the runner, because a wedged runner cannot time itself out.';
COMMENT ON COLUMN "jobs"."max_attempts" IS 'How many times this job may be retried automatically. Retries create attempt rows; the job row itself never changes.';
COMMENT ON COLUMN "jobs"."status" IS 'pending | blocked | queued | running | completed | skipped. Blocked means an upstream edge is unsatisfied, which is distinct from waiting for a runner.';
COMMENT ON COLUMN "jobs"."conclusion" IS 'success | failure | cancelled | skipped. Rolled up from the last attempt once the job settles.';

CREATE UNIQUE INDEX "uq_jobs_run_name"
ON "jobs" ("run_id", "name");
CREATE INDEX "idx_jobs_status_run"
ON "jobs" ("status", "run_id");

CREATE TABLE IF NOT EXISTS "job_dependencies" (
	-- The dependent job, the head of the edge. Half of the composite key; an edge table has no need for a surrogate id.
	"job_id" BIGINT,
	-- The job that must settle first, the tail of the edge. Both columns reference jobs in the same run, which is the invariant that keeps the graph acyclic and self-contained.
	"depends_on_job_id" BIGINT,
	-- on_success | on_failure | always | on_skipped. The edge, not the node, carries the condition, which is how a cleanup job runs only when a build fails.
	"condition" VARCHAR(24) NOT NULL DEFAULT 'on_success',
	PRIMARY KEY("job_id", "depends_on_job_id")
);

COMMENT ON TABLE "job_dependencies" IS 'One edge of the job DAG, stored as an adjacency list. Ready jobs are found by looking for nodes with no unsatisfied incoming edges; the reverse index is what makes unblocking dependants cheap when a job finishes.';
COMMENT ON COLUMN "job_dependencies"."job_id" IS 'The dependent job, the head of the edge. Half of the composite key; an edge table has no need for a surrogate id.';
COMMENT ON COLUMN "job_dependencies"."depends_on_job_id" IS 'The job that must settle first, the tail of the edge. Both columns reference jobs in the same run, which is the invariant that keeps the graph acyclic and self-contained.';
COMMENT ON COLUMN "job_dependencies"."condition" IS 'on_success | on_failure | always | on_skipped. The edge, not the node, carries the condition, which is how a cleanup job runs only when a build fails.';

CREATE INDEX "idx_job_dependencies_reverse"
ON "job_dependencies" ("depends_on_job_id");

CREATE TABLE IF NOT EXISTS "runners" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Runner identity, usually the hostname or an instance id.
	"name" VARCHAR(160) NOT NULL UNIQUE,
	-- shared | project | ephemeral. Ephemeral runners are destroyed after one job, which is the only honest way to run untrusted code.
	"scope" VARCHAR(16) NOT NULL DEFAULT 'shared',
	-- Project a dedicated runner is pinned to. Null for a shared runner.
	"project_id" BIGINT,
	-- offline | idle | busy | draining. Draining means finish the current job and accept no more, which is what a graceful deploy needs.
	"status" VARCHAR(16) NOT NULL DEFAULT 'offline',
	-- Slots on this machine. Above one, jobs on the same runner contend for disk and network, which shows up as mysterious flakiness.
	"max_concurrent_jobs" INTEGER NOT NULL DEFAULT 1,
	-- Last check-in. A runner silent for a few intervals is treated as offline and its jobs are requeued, which is why this is a column and not an in-memory fact.
	"last_heartbeat_at" TIMESTAMP,
	-- When the runner first connected.
	"registered_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "runners" IS 'A machine that executes jobs. Heartbeats live in the database rather than only in the scheduler memory so a scheduler restart does not lose track of what is running where.';
COMMENT ON COLUMN "runners"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "runners"."name" IS 'Runner identity, usually the hostname or an instance id.';
COMMENT ON COLUMN "runners"."scope" IS 'shared | project | ephemeral. Ephemeral runners are destroyed after one job, which is the only honest way to run untrusted code.';
COMMENT ON COLUMN "runners"."project_id" IS 'Project a dedicated runner is pinned to. Null for a shared runner.';
COMMENT ON COLUMN "runners"."status" IS 'offline | idle | busy | draining. Draining means finish the current job and accept no more, which is what a graceful deploy needs.';
COMMENT ON COLUMN "runners"."max_concurrent_jobs" IS 'Slots on this machine. Above one, jobs on the same runner contend for disk and network, which shows up as mysterious flakiness.';
COMMENT ON COLUMN "runners"."last_heartbeat_at" IS 'Last check-in. A runner silent for a few intervals is treated as offline and its jobs are requeued, which is why this is a column and not an in-memory fact.';
COMMENT ON COLUMN "runners"."registered_at" IS 'When the runner first connected.';

CREATE INDEX "idx_runners_status_heartbeat"
ON "runners" ("status", "last_heartbeat_at");

CREATE TABLE IF NOT EXISTS "runner_capabilities" (
	-- Runner being described. Half of the composite key.
	"runner_id" BIGINT,
	-- Capability name, e.g. os, arch, docker, gpu, node. The other half of the key, so a runner states each capability exactly once.
	"capability_key" VARCHAR(60),
	-- Value, e.g. linux, arm64, true, 24.3.0. Matching is exact string equality on purpose: version range logic in a scheduler is where mysterious placement bugs come from.
	"capability_value" VARCHAR(120) NOT NULL,
	PRIMARY KEY("runner_id", "capability_key")
);

COMMENT ON TABLE "runner_capabilities" IS 'What a runner can do, as key-value rows rather than a JSON blob, because the scheduler queries it every time a job becomes ready and needs an index on the pair.';
COMMENT ON COLUMN "runner_capabilities"."runner_id" IS 'Runner being described. Half of the composite key.';
COMMENT ON COLUMN "runner_capabilities"."capability_key" IS 'Capability name, e.g. os, arch, docker, gpu, node. The other half of the key, so a runner states each capability exactly once.';
COMMENT ON COLUMN "runner_capabilities"."capability_value" IS 'Value, e.g. linux, arm64, true, 24.3.0. Matching is exact string equality on purpose: version range logic in a scheduler is where mysterious placement bugs come from.';

CREATE INDEX "idx_runner_capabilities_lookup"
ON "runner_capabilities" ("capability_key", "capability_value");

CREATE TABLE IF NOT EXISTS "job_attempts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Job being executed.
	"job_id" BIGINT NOT NULL,
	-- Machine that picked it up. Null while queued, and it stays populated after the runner is deregistered so a failure can still be blamed correctly.
	"runner_id" BIGINT,
	-- Try number, starting at 1. A retry inserts a new row; the previous attempt logs, timings and artifacts stay reachable.
	"attempt_number" INTEGER NOT NULL,
	-- queued | running | completed | cancelled | lost. Lost means the runner stopped heartbeating mid-job, which is a different failure from the build failing.
	"status" VARCHAR(20) NOT NULL DEFAULT 'queued',
	-- success | failure | timed_out | cancelled | infrastructure_failure. Null until completed. Separating infrastructure failure from test failure is what stops a broken runner reading as a broken codebase.
	"conclusion" VARCHAR(20),
	-- Process exit status. Null when the job never started or was killed.
	"exit_code" INTEGER,
	-- When the attempt became schedulable.
	"queued_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When the runner began executing.
	"started_at" TIMESTAMP,
	-- When it stopped.
	"finished_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "job_attempts" IS 'One execution of one job on one runner. This is the only table in the schema that describes reality rather than intent, and it is where every timing metric actually comes from.';
COMMENT ON COLUMN "job_attempts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "job_attempts"."job_id" IS 'Job being executed.';
COMMENT ON COLUMN "job_attempts"."runner_id" IS 'Machine that picked it up. Null while queued, and it stays populated after the runner is deregistered so a failure can still be blamed correctly.';
COMMENT ON COLUMN "job_attempts"."attempt_number" IS 'Try number, starting at 1. A retry inserts a new row; the previous attempt logs, timings and artifacts stay reachable.';
COMMENT ON COLUMN "job_attempts"."status" IS 'queued | running | completed | cancelled | lost. Lost means the runner stopped heartbeating mid-job, which is a different failure from the build failing.';
COMMENT ON COLUMN "job_attempts"."conclusion" IS 'success | failure | timed_out | cancelled | infrastructure_failure. Null until completed. Separating infrastructure failure from test failure is what stops a broken runner reading as a broken codebase.';
COMMENT ON COLUMN "job_attempts"."exit_code" IS 'Process exit status. Null when the job never started or was killed.';
COMMENT ON COLUMN "job_attempts"."queued_at" IS 'When the attempt became schedulable.';
COMMENT ON COLUMN "job_attempts"."started_at" IS 'When the runner began executing.';
COMMENT ON COLUMN "job_attempts"."finished_at" IS 'When it stopped.';

CREATE UNIQUE INDEX "uq_job_attempts_job_attempt"
ON "job_attempts" ("job_id", "attempt_number");
CREATE INDEX "idx_job_attempts_runner_started"
ON "job_attempts" ("runner_id", "started_at");
CREATE INDEX "idx_job_attempts_status_queued"
ON "job_attempts" ("status", "queued_at");

CREATE TABLE IF NOT EXISTS "artifacts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Attempt that produced it. Attached to the attempt rather than the job, so a retry does not overwrite what the first try uploaded.
	"job_attempt_id" BIGINT NOT NULL,
	-- Logical artifact name, e.g. dist or coverage-report. Downstream jobs request it by this name.
	"name" VARCHAR(200) NOT NULL,
	-- Object storage path. Unique so a replayed upload cannot register the same blob twice.
	"storage_key" VARCHAR(500) NOT NULL UNIQUE,
	-- Uncompressed size. BIGINT because container images pass four gigabytes without trying.
	"size_bytes" BIGINT NOT NULL,
	-- Checksum of the uploaded bytes. Lets a consumer verify what it downloaded and lets storage deduplicate identical builds.
	"content_sha256" CHAR(64) NOT NULL,
	-- Deletion deadline, computed from the project retention setting at upload time. Stored per artifact so changing the policy does not retroactively delete things people are relying on.
	"expires_at" TIMESTAMP NOT NULL,
	-- Upload time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "artifacts" IS 'A build output. Artifacts are immutable and expiring: the row and the object are deleted together by a sweeper reading the expiry index, which is the only reliable way to keep a CI storage bill flat.';
COMMENT ON COLUMN "artifacts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "artifacts"."job_attempt_id" IS 'Attempt that produced it. Attached to the attempt rather than the job, so a retry does not overwrite what the first try uploaded.';
COMMENT ON COLUMN "artifacts"."name" IS 'Logical artifact name, e.g. dist or coverage-report. Downstream jobs request it by this name.';
COMMENT ON COLUMN "artifacts"."storage_key" IS 'Object storage path. Unique so a replayed upload cannot register the same blob twice.';
COMMENT ON COLUMN "artifacts"."size_bytes" IS 'Uncompressed size. BIGINT because container images pass four gigabytes without trying.';
COMMENT ON COLUMN "artifacts"."content_sha256" IS 'Checksum of the uploaded bytes. Lets a consumer verify what it downloaded and lets storage deduplicate identical builds.';
COMMENT ON COLUMN "artifacts"."expires_at" IS 'Deletion deadline, computed from the project retention setting at upload time. Stored per artifact so changing the policy does not retroactively delete things people are relying on.';
COMMENT ON COLUMN "artifacts"."created_at" IS 'Upload time.';

CREATE UNIQUE INDEX "uq_artifacts_attempt_name"
ON "artifacts" ("job_attempt_id", "name");
CREATE INDEX "idx_artifacts_expires"
ON "artifacts" ("expires_at");

CREATE TABLE IF NOT EXISTS "cache_entries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Project the cache is scoped to. Cross-project cache sharing is a security hole, not a feature.
	"project_id" BIGINT NOT NULL,
	-- Attempt that wrote it, for provenance. Null once that attempt has been pruned, which the cache must survive.
	"created_by_attempt_id" BIGINT,
	-- Exact key, usually a hash of a lockfile, e.g. npm-linux-9f2c. Exact matches restore; prefix matches are a fallback.
	"cache_key" VARCHAR(400) NOT NULL,
	-- Restore-key prefix, indexed separately so a near-miss can fall back to the most recent compatible cache instead of rebuilding from nothing.
	"key_prefix" VARCHAR(200) NOT NULL,
	-- Branch the cache belongs to. Branch caches fall back to the default branch, which is what stops one feature branch poisoning everyone else.
	"scope_ref" VARCHAR(255) NOT NULL,
	-- Object storage path of the archive.
	"storage_key" VARCHAR(500) NOT NULL UNIQUE,
	-- Archive size, used to enforce a per-project cache quota by evicting the least recently used.
	"size_bytes" BIGINT NOT NULL,
	-- Last restore. Eviction is least-recently-used, so this column is written far more often than it is read.
	"last_used_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When it was saved.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "cache_entries" IS 'A restorable cache archive. Unlike an artifact it is a performance optimisation with no correctness guarantee: any entry can vanish at any time and the build must still work, just slower.';
COMMENT ON COLUMN "cache_entries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "cache_entries"."project_id" IS 'Project the cache is scoped to. Cross-project cache sharing is a security hole, not a feature.';
COMMENT ON COLUMN "cache_entries"."created_by_attempt_id" IS 'Attempt that wrote it, for provenance. Null once that attempt has been pruned, which the cache must survive.';
COMMENT ON COLUMN "cache_entries"."cache_key" IS 'Exact key, usually a hash of a lockfile, e.g. npm-linux-9f2c. Exact matches restore; prefix matches are a fallback.';
COMMENT ON COLUMN "cache_entries"."key_prefix" IS 'Restore-key prefix, indexed separately so a near-miss can fall back to the most recent compatible cache instead of rebuilding from nothing.';
COMMENT ON COLUMN "cache_entries"."scope_ref" IS 'Branch the cache belongs to. Branch caches fall back to the default branch, which is what stops one feature branch poisoning everyone else.';
COMMENT ON COLUMN "cache_entries"."storage_key" IS 'Object storage path of the archive.';
COMMENT ON COLUMN "cache_entries"."size_bytes" IS 'Archive size, used to enforce a per-project cache quota by evicting the least recently used.';
COMMENT ON COLUMN "cache_entries"."last_used_at" IS 'Last restore. Eviction is least-recently-used, so this column is written far more often than it is read.';
COMMENT ON COLUMN "cache_entries"."created_at" IS 'When it was saved.';

CREATE UNIQUE INDEX "uq_cache_entries_project_key_scope"
ON "cache_entries" ("project_id", "cache_key", "scope_ref");
CREATE INDEX "idx_cache_entries_prefix_lru"
ON "cache_entries" ("project_id", "key_prefix", "last_used_at");

CREATE TABLE IF NOT EXISTS "job_log_chunks" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Attempt the output belongs to. Logs are per attempt, because the reason to keep a failed attempt at all is to read what it said.
	"job_attempt_id" BIGINT NOT NULL,
	-- Chunk order within the attempt. Runners stream out of order over unreliable networks, so ordering is explicit rather than by arrival.
	"sequence" INTEGER NOT NULL,
	-- Start offset within the full log. Lets the browser tail from a position and resume after a disconnect without refetching megabytes.
	"byte_offset" BIGINT NOT NULL,
	-- Raw log bytes including ANSI escapes. Kept verbatim so colours and progress bars render exactly as the tool emitted them.
	"content" TEXT NOT NULL,
	-- Marks the last chunk. Without it a truncated upload is indistinguishable from a log that is still streaming.
	"is_final" BOOLEAN NOT NULL DEFAULT false,
	-- When the chunk arrived at the server.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "job_log_chunks" IS 'Streamed build output in ordered chunks. Chunking rather than one growing column is what allows live tailing, resumable readers and archiving old logs to object storage without touching the rest of the schema.';
COMMENT ON COLUMN "job_log_chunks"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "job_log_chunks"."job_attempt_id" IS 'Attempt the output belongs to. Logs are per attempt, because the reason to keep a failed attempt at all is to read what it said.';
COMMENT ON COLUMN "job_log_chunks"."sequence" IS 'Chunk order within the attempt. Runners stream out of order over unreliable networks, so ordering is explicit rather than by arrival.';
COMMENT ON COLUMN "job_log_chunks"."byte_offset" IS 'Start offset within the full log. Lets the browser tail from a position and resume after a disconnect without refetching megabytes.';
COMMENT ON COLUMN "job_log_chunks"."content" IS 'Raw log bytes including ANSI escapes. Kept verbatim so colours and progress bars render exactly as the tool emitted them.';
COMMENT ON COLUMN "job_log_chunks"."is_final" IS 'Marks the last chunk. Without it a truncated upload is indistinguishable from a log that is still streaming.';
COMMENT ON COLUMN "job_log_chunks"."created_at" IS 'When the chunk arrived at the server.';

CREATE UNIQUE INDEX "uq_job_log_chunks_attempt_sequence"
ON "job_log_chunks" ("job_attempt_id", "sequence");

